BEGIN;
CREATE TABLE shopping.lists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120),description text NOT NULL DEFAULT '',sort_order bigint NOT NULL DEFAULT 0,archived_at timestamptz,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id));
CREATE TABLE shopping.items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),list_id uuid NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200),quantity numeric(18,6) CHECK(quantity>0),unit_code text REFERENCES core.units(code),group_name text NOT NULL DEFAULT '',note text NOT NULL DEFAULT '',sort_order bigint NOT NULL DEFAULT 0,checked_at timestamptz,checked_by uuid REFERENCES core.users(id),created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,list_id) REFERENCES shopping.lists(household_id,id) ON DELETE CASCADE,CHECK((checked_at IS NULL)=(checked_by IS NULL)));
CREATE INDEX items_list_order ON shopping.items(household_id,list_id,sort_order,id);
CREATE TABLE shopping.item_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),item_id uuid NOT NULL,action text NOT NULL,actor_user_id uuid NOT NULL REFERENCES core.users(id),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT USAGE ON SCHEMA shopping TO household_app; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA shopping TO household_app;
COMMIT;
